export function normalizePostgresConnectionString(connectionString: string) {
  const url = new URL(connectionString);
  const isSupabasePooler = url.hostname === 'pooler.supabase.com' || url.hostname.endsWith('.pooler.supabase.com');
  if (process.env.VERCEL && isSupabasePooler && url.port === '5432') url.port = '6543';
  url.searchParams.delete('sslmode');
  url.searchParams.delete('uselibpqcompat');
  return url.toString();
}

export function postgresPoolConfig(connectionString: string): PoolConfig {
  const url = new URL(connectionString);
  const sslMode = url.searchParams.get('sslmode');
  const isSupabase = url.hostname.endsWith('.supabase.com');
  if (isSupabase && sslMode === 'disable') throw new Error('Supabase PostgreSQL connections must use TLS');
  const caPath = process.env.PGSSLROOTCERT || (isSupabase ? bundledSupabaseCa : undefined);
  const ssl = isSupabase || (sslMode && sslMode !== 'disable')
    ? {rejectUnauthorized: true, ...(caPath ? {ca: fs.readFileSync(caPath, 'utf8')} : {})}
    : undefined;
  return {
    connectionString: normalizePostgresConnectionString(connectionString),
    ssl,
    max: process.env.VERCEL ? 2 : 3,
    connectionTimeoutMillis: 10_000,
    idleTimeoutMillis: 30_000,
    allowExitOnIdle: Boolean(process.env.VERCEL),
    options: process.env.VERCEL ? undefined : '-c timezone=UTC',
  };
}

type Queryable = {query(text: string, values?: any[]): Promise<QueryResult<any>>};

// Converts the legacy SQLite-style parameter marker while preserving question
// marks inside SQL literals, quoted identifiers, dollar-quoted bodies, and
// comments. New queries should prefer native PostgreSQL $1…$n parameters.
export function postgresSql(sql: string) {
  let output = '';
  let parameter = 0;
  let index = 0;
  let state: 'normal' | 'single' | 'double' | 'line' | 'block' | 'dollar' = 'normal';
  let dollarTag = '';
  while (index < sql.length) {
    const char = sql[index];
    const next = sql[index + 1];
    if (state === 'normal') {
      if (char === "'") state = 'single';
      else if (char === '"') state = 'double';
      else if (char === '-' && next === '-') { state = 'line'; output += '--'; index += 2; continue; }
      else if (char === '/' && next === '*') { state = 'block'; output += '/*'; index += 2; continue; }
      else if (char === '$') {
        const match = sql.slice(index).match(/^\$[A-Za-z_][A-Za-z0-9_]*\$|^\$\$/);
        if (match) { state = 'dollar'; dollarTag = match[0]; output += dollarTag; index += dollarTag.length; continue; }
      } else if (char === '?') { output += `$${++parameter}`; index++; continue; }
    } else if (state === 'single' && char === "'") {
      if (next === "'") { output += char + next; index += 2; continue; }
      state = 'normal';
    } else if (state === 'double' && char === '"') {
      if (next === '"') { output += char + next; index += 2; continue; }
      state = 'normal';
    } else if (state === 'line' && char === '\n') state = 'normal';
    else if (state === 'block' && char === '*' && next === '/') { output += char + next; index += 2; state = 'normal'; continue; }
    else if (state === 'dollar' && sql.startsWith(dollarTag, index)) {
      output += dollarTag; index += dollarTag.length; state = 'normal'; continue;
    }
    output += char;
    index++;
  }
  return output;
}

export class DB {
  private readonly transactions = new AsyncLocalStorage<PoolClient>();
  constructor(private readonly pool: Pool) {}
  private executor(): Queryable { return this.transactions.getStore() ?? this.pool; }
  query(text: string, values: any[] = []) { return this.executor().query(text, values); }
  prepare(sql: string) {
    const text = postgresSql(sql);
    return {
      get: async (...values: any[]) => (await this.executor().query(text, values)).rows[0],
      all: async (...values: any[]) => (await this.executor().query(text, values)).rows,
      run: async (...values: any[]) => {
        const result = await this.executor().query(text, values);
        return {changes: result.rowCount ?? 0, rows: result.rows, lastInsertRowid: result.rows[0]?.id};
      },
    };
  }
  async transaction<T>(fn: (db: DB) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();
    try { await client.query('BEGIN'); const value = await this.transactions.run(client, () => fn(this)); await client.query('COMMIT'); return value; }
    catch (error) { await client.query('ROLLBACK'); throw error; }
    finally { client.release(); }
  }
  async migrate({advisoryLock = true, compatibilityMigrations = true}: {advisoryLock?: boolean; compatibilityMigrations?: boolean} = {}) {
    await this.transaction(async () => {
      if (advisoryLock) await this.query('SELECT pg_advisory_xact_lock($1)', [2026082401]);
      await this.query(`CREATE TABLE IF NOT EXISTS schema_migrations(
        version INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        checksum TEXT NOT NULL,
        applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
      )`);
      const applied = new Map((await this.query('SELECT version,checksum FROM schema_migrations')).rows.map((row: any) => [row.version, row.checksum]));
      const migrations = [
        {version: 1, name: 'initial PostgreSQL schema', sql: compatibilityMigrations ? schemaSql : freshSchemaSql},
        ...(compatibilityMigrations ? [{version: 2, name: 'PostgreSQL native temporal and JSON types', sql: nativeTypesMigrationSql}] : []),
        {version: 3, name: 'password recovery tokens', sql: passwordResetMigrationSql},
        {version: 4, name: 'workspace invite refresh cooldown', sql: inviteRefreshMigrationSql},
        {version: 5, name: 'remove password recovery', sql: removePasswordRecoveryMigrationSql},
        {version: 6, name: 'report timezone and detailed evidence consent', sql: reportEvidenceMigrationSql},
        {version: 9, name: 'prompted report regeneration', sql: reportRegenerationMigrationSql},
        {version: 11, name: 'report naming', sql: reportNamingMigrationSql},
        {version: 12, name: 'hide removed revoked devices', sql: removedDevicesMigrationSql},
        {version: 13, name: 'repository selection', sql: compatibilityMigrations ? repositorySelectionMigrationSql : freshRepositorySelectionMigrationSql},
        {version: 14, name: 'enforce repository selection at ingestion', sql: repositorySelectionEnforcementMigrationSql},
        {version: 15, name: 'repository selection lifecycle fencing', sql: repositorySelectionLifecycleMigrationSql},
        {version: 16, name: 'account-level device installation identity', sql: compatibilityMigrations ? accountDeviceMigrationSql : freshAccountDeviceMigrationSql},
        {version: 17, name: 'recipient invitation inbox and Developer role', sql: compatibilityMigrations ? invitationInboxMigrationSql : freshInvitationInboxMigrationSql},
        {version: 18, name: 'report presentation format and scope', sql: reportFormatMigrationSql},
        {version: 19, name: 'workspace report schedules', sql: reportScheduleMigrationSql},
        {version: 20, name: 'optional Slack report notifications', sql: slackReportNotificationMigrationSql},
        {version: 21, name: 'shared activity observations', sql: sharedActivityMigrationSql},
        {version: 22, name: 'scheduled report naming', sql: reportScheduleNamingMigrationSql},
        {version: 23, name: 'canonical engineer names', sql: canonicalEngineerNamesMigrationSql},
      ];
      for (const migration of migrations) {
        const checksum = crypto.createHash('sha256').update(migration.sql).digest('hex');
        if (applied.has(migration.version)) {
          if (applied.get(migration.version) !== checksum) throw new Error(`PostgreSQL migration ${migration.version} checksum mismatch`);
          continue;
        }
        await this.query(migration.sql);
        await this.query('INSERT INTO schema_migrations(version,name,checksum) VALUES($1,$2,$3)', [migration.version, migration.name, checksum]);
      }
      const observations = await this.prepare(`SELECT DISTINCT e.id,e.agent_id,e.type,e.occurred_at,e.data,c.local_key,c.repository_fingerprint
        FROM activity_events e JOIN activity_event_repositories aer ON aer.event_id=e.id
        JOIN repository_candidates c ON c.repository_id=aer.repository_id
        WHERE c.repository_fingerprint IS NOT NULL ORDER BY e.id`).all();
      const keepers = new Map<string, number>();
      const removed = new Set<number>();
      for (const observation of observations as any[]) {
        const key = JSON.stringify([observation.agent_id, observation.local_key, observation.repository_fingerprint, observation.type, observation.occurred_at, observation.data]);
        const keeper = keepers.get(key) || Number(observation.id);
        keepers.set(key, keeper);
        await this.prepare(`INSERT INTO activity_event_repositories(event_id,repository_id)
          SELECT ?,repository_id FROM repository_candidates WHERE agent_id=? AND local_key=? AND repository_fingerprint=? AND desired_traced=TRUE AND repository_id IS NOT NULL
          ON CONFLICT DO NOTHING`).run(keeper, observation.agent_id, observation.local_key, observation.repository_fingerprint);
        if (keeper !== Number(observation.id) && !removed.has(Number(observation.id))) {
          await this.prepare('INSERT INTO activity_event_repositories(event_id,repository_id) SELECT ?,repository_id FROM activity_event_repositories WHERE event_id=? ON CONFLICT DO NOTHING').run(keeper, observation.id);
          await this.prepare('DELETE FROM activity_events WHERE id=?').run(observation.id);
          removed.add(Number(observation.id));
        }
      }
    });
  }
  async close() { await this.pool.end(); }
}

export async function openPostgresDb(connectionString: string, {migrate = true}: {migrate?: boolean} = {}) {
  const pool = new Pool(postgresPoolConfig(connectionString));
  pool.on('error', (error) => console.error('PostgreSQL idle client error:', error.message));
  const db = new DB(pool);
  try {
    if (migrate) await db.migrate();
    return db;
  } catch (error) {
    await db.close();
    throw error;
  }
}
